from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )

        self.spy_option = self.add_option("SPY", Resolution.MINUTE)
        self.spy_option.set_filter(
            -1000,
            1000,
            timedelta(days=0),
            timedelta(days=365)
        )

        self._five_minute_closes = deque(maxlen=21)
        self._pending_entry_signal = False
        self._signal_bar_end = None

        self._entry_order_id = None
        self._exit_order_id = None
        self._spy_cleanup_order_id = None

        self._held_option = None
        self._held_expiry = None
        self._entry_fill_price = None
        self._blocked_entry_date = None

        self._five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute_consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(
            self.spy.symbol,
            self._five_minute_consolidator
        )

    def on_data(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self._has_open_option_position():
            self._evaluate_option_exits(data)

        # The consolidator has already processed the minute bar for this Slice.
        # Evaluate a signal once, on the same Slice as the completed five-minute bar.
        if self._pending_entry_signal:
            self._pending_entry_signal = False

            if self._blocked_entry_date == self.time.date():
                return

            if self._has_open_option_position() or self._entry_order_id is not None:
                return

            self._submit_entry_from_current_slice(data)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        self._five_minute_closes.append(float(bar.close))

        # To compare the prior completed slow SMA with the current slow SMA,
        # 21 actual five-minute closes are required.
        if len(self._five_minute_closes) < 21:
            return

        closes = list(self._five_minute_closes)

        previous_closes = closes[:-1]
        fast_previous = sum(previous_closes[-5:]) / 5.0
        slow_previous = sum(previous_closes[-20:]) / 20.0

        fast_current = sum(closes[-5:]) / 5.0
        slow_current = sum(closes[-20:]) / 20.0

        is_bullish_cross = (
            fast_previous <= slow_previous and
            fast_current > slow_current
        )

        bar_end_time = bar.end_time.time()
        valid_entry_time = (
            time(9, 45) <= bar_end_time <= time(14, 30)
        )

        if is_bullish_cross and valid_entry_time:
            self._pending_entry_signal = True
            self._signal_bar_end = bar.end_time

    def _submit_entry_from_current_slice(self, data: Slice):
        spy_bar = data.bars.get(self.spy.symbol)
        if spy_bar is None or spy_bar.close <= 0:
            self.debug("Entry skipped: SPY has no current minute TradeBar.")
            return

        if not data.option_chains:
            self.debug("Entry skipped: current Slice has no SPY option chain.")
            return

        current_spy_price = float(spy_bar.close)
        minimum_expiry = self.time.date() + timedelta(days=7)

        contracts = []
        for chain in data.option_chains.values():
            for contract in chain:
                if contract.right != OptionRight.CALL:
                    continue

                expiry_date = contract.expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                contracts.append(contract)

        if not contracts:
            self.debug("Entry skipped: no call expiration is at least 7 calendar days away.")
            return

        selected_expiry = min(contract.expiry.date() for contract in contracts)
        minimum_strike = current_spy_price * 1.01

        eligible_contracts = [
            contract for contract in contracts
            if contract.expiry.date() == selected_expiry
            and float(contract.strike) >= minimum_strike
        ]

        if not eligible_contracts:
            self.debug(
                "Entry skipped: no qualifying call strike at the selected expiration."
            )
            return

        selected = min(
            eligible_contracts,
            key=lambda contract: (float(contract.strike), str(contract.symbol))
        )

        ticket = self.market_order(selected.symbol, 1)
        self._entry_order_id = ticket.order_id

        self.debug(
            f"Entry submitted: {selected.symbol}, expiry {selected.expiry.date()}, "
            f"strike {selected.strike}."
        )

    def _evaluate_option_exits(self, data: Slice):
        if self._held_option is None or self._entry_fill_price is None:
            return

        quantity = self.portfolio[self._held_option].quantity
        if quantity <= 0:
            return

        # Time stop applies even if this Slice contains no usable option quote.
        if (
            self.time.date() == self._previous_trading_day(self._held_expiry) and
            self.time.hour == 15 and
            self.time.minute == 45
        ):
            self._submit_option_exit("time stop before expiration")
            return

        quote = self._current_option_quote(data, self._held_option)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_option_exit("50% profit target")

    def _current_option_quote(self, data: Slice, symbol):
        for chain in data.option_chains.values():
            for contract in chain:
                if contract.symbol != symbol:
                    continue

                bid = float(contract.bid_price)
                ask = float(contract.ask_price)

                if bid > 0 and ask > 0:
                    return bid, ask

        return None

    def _submit_option_exit(self, reason: str):
        if self._held_option is None:
            return

        quantity = self.portfolio[self._held_option].quantity
        if quantity <= 0:
            return

        # Ensure only one exit order remains open for the option.
        for order in self.transactions.get_open_orders(self._held_option):
            if order.direction == OrderDirection.SELL:
                self.transactions.cancel_order(order.id)

        ticket = self.market_order(self._held_option, -quantity)
        self._exit_order_id = ticket.order_id
        self.debug(f"Exit submitted ({reason}): {self._held_option}.")

    def _handle_expiration_processing(self):
        if not self._has_open_option_position():
            return

        if self.time.date() >= self._held_expiry:
            self._blocked_entry_date = self.time.date()
            self.debug(
                f"Expiration processing: liquidating remaining option {self._held_option}."
            )
            self._submit_option_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy.symbol].quantity
        if quantity == 0 or self._spy_cleanup_order_id is not None:
            return

        ticket = self.market_order(self.spy.symbol, -quantity)
        self._spy_cleanup_order_id = ticket.order_id
        self.debug(
            f"Unexpected SPY position from exercise/assignment: "
            f"submitting liquidation for {quantity} shares."
        )

    def _has_open_option_position(self):
        return (
            self._held_option is not None and
            self.portfolio[self._held_option].quantity > 0
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy.symbol].exchange.hours

        while not exchange_hours.is_date_open(
            datetime.combine(candidate, time.min),
            False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def on_order_event(self, order_event: OrderEvent):
        if order_event.order_id == self._entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self._held_option = order_event.symbol
                self._held_expiry = order_event.symbol.id.date.date()
                self._entry_fill_price = float(order_event.fill_price)
                self._entry_order_id = None

                self.debug(
                    f"Entry filled: {self._held_option} at "
                    f"{self._entry_fill_price:.2f}."
                )

            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self.debug(f"Entry order closed without fill: {order_event.symbol}.")
                self._entry_order_id = None

        if order_event.order_id == self._exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"Exit filled: {order_event.symbol} at "
                    f"{float(order_event.fill_price):.2f}."
                )
                self._exit_order_id = None
                self._held_option = None
                self._held_expiry = None
                self._entry_fill_price = None

            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self._exit_order_id = None

        if order_event.order_id == self._spy_cleanup_order_id:
            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
                OrderStatus.REJECTED
            ):
                self._spy_cleanup_order_id = None
