from AlgorithmImports import *
from datetime import datetime, timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(-100, 100, timedelta(days=0), timedelta(days=180))
        self.option_symbol = option_security.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.pending_entry_bar_end = None
        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        is_bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if is_bullish_cross and self._is_entry_time(bar.EndTime):
            # Process on the Slice bearing this completed bar's end time.
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, data):
        self._handle_unexpected_spy_position()

        if self.held_contract is not None:
            if self._is_expiration_day():
                self.no_entry_date = self.Time.date()
                self._submit_exit("expiration safety exit")
                return

            if self._is_pre_expiration_time_stop():
                self._submit_exit("15:45 pre-expiration exit")
                return

            self._check_profit_target(data)
            return

        if self.entry_order_id is not None:
            return

        if self.pending_entry_bar_end is None:
            return

        # A skipped crossover is never queued for a later Slice.
        if self.Time != self.pending_entry_bar_end:
            if self.Time > self.pending_entry_bar_end:
                self.pending_entry_bar_end = None
            return

        self.pending_entry_bar_end = None

        if self.no_entry_date == self.Time.date():
            return

        self._try_enter_from_current_chain(data)

    def _try_enter_from_current_chain(self, data):
        try:
            chain = data.OptionChains.get(self.option_symbol)
        except Exception:
            chain = None

        if chain is None:
            self.Debug(f"{self.Time}: entry skipped; no SPY option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: entry skipped; invalid SPY price.")
            return

        today = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not expirations:
            self.Debug(f"{self.Time}: entry skipped; no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: entry skipped; no qualifying call for {selected_expiry}."
            )
            return

        contract = min(
            candidates,
            key=lambda x: (float(x.Strike), str(x.Symbol))
        )

        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: submitted entry for {contract.Symbol} "
            f"(strike {contract.Strike}, expiry {contract.Expiry.date()})."
        )

    def _check_profit_target(self, data):
        if self.entry_price is None or self.entry_price <= 0:
            return

        try:
            quote = data.QuoteBars.get(self.held_contract)
        except Exception:
            quote = None

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit(
                f"profit target hit; midpoint {midpoint:.2f}, entry {self.entry_price:.2f}"
            )

    def _submit_exit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        # Remove any other outstanding exit instruction before the market exit.
        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: submitted exit for {self.held_contract}; {reason}.")

    def OnOrderEvent(self, orderEvent):
        if self.entry_order_id is not None and orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled and orderEvent.FillQuantity > 0:
                self.held_contract = orderEvent.Symbol
                self.entry_price = orderEvent.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: entry filled for {self.held_contract} "
                    f"at {self.entry_price:.2f}."
                )
            elif orderEvent.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: entry order {orderEvent.OrderId} did not fill.")
                self.entry_order_id = None

