from datetime import timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA, False)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        # State for manually aligned New York five-minute bars.
        self.bucket_start = None
        self.bucket_close = None

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_cleanup_order_id = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(15, 45),
            self.ExitBeforeExpiration
        )

    def OnData(self, data: Slice):
        self.HandleUnexpectedSpyPosition()

        # Expiration-day protection takes priority over all new signals.
        if self.HasOptionPosition() and self.Time.date() >= self.held_contract.ID.Date.date():
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration protection")
            return

        self.EvaluateProfitTarget(data)
        self.UpdateFiveMinuteBar(data)

    def UpdateFiveMinuteBar(self, data: Slice):
        if self.spy_symbol not in data.Bars:
            return

        minute_bar = data.Bars[self.spy_symbol]

        # SPY regular-session minute bars are timestamped by their start time.
        if not (time(9, 30) <= minute_bar.Time.time() < time(16, 0)):
            return

        bucket_start = minute_bar.Time.replace(
            minute=(minute_bar.Time.minute // 5) * 5,
            second=0,
            microsecond=0
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        # A new bucket without a closing minute from the previous one means the
        # previous five-minute bar was missing; it is deliberately discarded.
        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_close = None

        self.bucket_close = minute_bar.Close

        # This produces bars ending on NY clock boundaries: 09:35, 09:40, etc.
        if minute_bar.EndTime != bucket_end:
            return

        self.OnFiveMinuteBar(bucket_end, self.bucket_close, data)
        self.bucket_start = None
        self.bucket_close = None

    def OnFiveMinuteBar(self, bar_end, close, data: Slice):
        prior_ready = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value if prior_ready else None
        prior_slow = self.slow.Current.Value if prior_ready else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        crossed_up = (
            prior_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not crossed_up:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.HasOptionPosition() or self.entry_order_id is not None:
            return

        self.TryEnter(data, close)

    def TryEnter(self, data: Slice, spy_price):
        chain = None
        for canonical_symbol, candidate_chain in data.OptionChains.items():
            if canonical_symbol == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in Slice")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away")
            return

