        session_close_end = datetime.combine(end_time.date(), time(16, 0))

        if end_time < session_open_end or end_time > session_close_end:
            self._reset_five_minute_builder()
            return

        if (
            self._next_expected_minute_end is not None
            and end_time != self._next_expected_minute_end
        ):
