    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min), False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_option_exit(self, reason: str):
        if self._held_option is None or not self.Portfolio[self._held_option].Invested:
            return

        if self._is_order_open(self._exit_order_id):
            return

        for order in self.Transactions.GetOpenOrders(self._held_option):
            self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self._held_option].Quantity
        ticket = self.MarketOrder(self._held_option, quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self._held_option} | {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_fill_price = float(order_event.FillPrice)
                self._entry_order_id = None
                self.Debug(
                    f"Entry filled: {self._held_option} @ {self._entry_fill_price:.2f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}")
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} @ {float(order_event.FillPrice):.2f}"
                )
                self._held_option = None
                self._entry_fill_price = None
                self._exit_order_id = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._exit_order_id = None

        if order_event.OrderId == self._spy_cleanup_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._spy_cleanup_order_id = None

    def _is_order_open(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )
