        quote = data.QuoteBars.get(self._held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0 or self._entry_fill_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_option_exit("50% profit target reached")

    def _process_expiration_safety(self):
        if self._held_option is None or not self.Portfolio[self._held_option].Invested:
            return

        expiry = self._held_option.ID.Date.date()

        if self.Time.date() >= expiry:
            self._blocked_entry_date = self.Time.date()
            self._submit_option_exit("expiration safety liquidation")
            return

        if (
            self.Time.time() == time(15, 45)
            and self.Time.date() == self._previous_trading_day(expiry)
        ):
            self._submit_option_exit("15:45 pre-expiration liquidation")

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min), False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_option_exit(self, reason: str):
